/**
 * fallback.ts — Built-in deterministic fallback generator when Gemini is absent or offline.
 *
 * SPEC REQUIREMENT (§6):
 * Fallback: template-based ideas and rule-based interview results.
 * The UI shows "Generated by the built-in planner" when fallback is used.
 */

import type {
  InterviewResult,
  IdeasResult,
  ParseResult,
  AssistantResult,
  InterviewAnswers,
  IdeasRequest,
  ParseRequest,
  AssistantRequest,
} from '../schemas/ai';
import { getTemplate } from '../engine/templates';

/** Rule-based interview parser generating 5-8 moments based on host answers */
export function generateFallbackInterview(req: InterviewAnswers): InterviewResult {
  const { eventType, answers } = req;
  const template = getTemplate(eventType);

  // We synthesize moments from the template, personalized using keywords in answers
  const answerBlob = answers.join(' ').toLowerCase();

  const moments = template.moments.slice(0, 7).map((tmplMoment) => {
    let why = `Key traditional moment for a ${eventType}.`;
    if (answerBlob.includes('music') || answerBlob.includes('dance')) {
      if (tmplMoment.name.toLowerCase().includes('dance') || tmplMoment.name.toLowerCase().includes('welcome')) {
        why = 'Tailored to your love of music and dancing.';
      }
    } else if (answerBlob.includes('food') || answerBlob.includes('dinner')) {
      if (tmplMoment.name.toLowerCase().includes('dinner') || tmplMoment.name.toLowerCase().includes('toast')) {
        why = 'Focused on communal dining and shared stories.';
      }
    } else if (answerBlob.includes('intimate') || answerBlob.includes('family')) {
      if (tmplMoment.importance >= 4) {
        why = 'Selected to foster close connection with your inner circle.';
      }
    }

    return {
      name: tmplMoment.name,
      importance: tmplMoment.importance,
      why,
    };
  });

  return {
    moments,
    source: 'fallback',
  };
}

/** Template-based ideas per moment at 3 distinct budget tiers */
export function generateFallbackIdeas(req: IdeasRequest): IdeasResult {
  const { momentName, momentBudgetMinor } = req;
  const budgetPaise = momentBudgetMinor > 0 ? momentBudgetMinor : 2_000_000;

  return {
    ideas: [
      {
        tier: 'simple',
        text: `Intimate, host-led presentation for "${momentName}" featuring handwritten prompts or a shared acoustic playlist.`,
        estimateMinor: Math.round(budgetPaise * 0.2),
      },
      {
        tier: 'standard',
        text: `Curated thematic styling and dedicated ambient lighting package to elevate "${momentName}" with personalized guest favors.`,
        estimateMinor: Math.round(budgetPaise * 0.6),
      },
      {
        tier: 'special',
        text: `Signature choreographed reveal or live acoustic performance tailored specifically for "${momentName}" with custom keepsake photography.`,
        estimateMinor: Math.round(budgetPaise * 1.0),
      },
    ],
    source: 'fallback',
  };
}

/** Rule-based brief parser extracting candidate event fields from unstructured text */
export function generateFallbackParse(req: ParseRequest): ParseResult {
  const text = req.brief.toLowerCase();

  let type: 'wedding' | 'birthday' | 'community' = 'wedding';
  if (text.includes('birthday') || text.includes('bday') || text.includes('turning')) {
    type = 'birthday';
  } else if (text.includes('community') || text.includes('festival') || text.includes('fundraiser') || text.includes('cultural')) {
    type = 'community';
  }

  // Extract guest count heuristically (e.g. "150 guests", "200 people")
  let guests = 100;
  const guestMatch = /(\d+)\s*(guests?|people|pax|attendees?)/i.exec(req.brief);
  if (guestMatch?.[1]) {
    const parsedGuests = parseInt(guestMatch[1], 10);
    if (!isNaN(parsedGuests) && parsedGuests > 0) guests = parsedGuests;
  }

  // Extract budget heuristically (e.g. "5 lakhs", "5,00,000", "500000")
  let budgetMinor = 50_000_000; // ₹5,00,000 default
  const lakhMatch = /(\d+(?:\.\d+)?)\s*(?:lakhs?|lac|l)/i.exec(req.brief);
  if (lakhMatch?.[1]) {
    const lakhs = parseFloat(lakhMatch[1]);
    if (!isNaN(lakhs) && lakhs > 0) budgetMinor = Math.round(lakhs * 100_000 * 100);
  }

  // City detection heuristics
  const cities = ['Mumbai', 'Delhi', 'Bengaluru', 'Bangalore', 'Jaipur', 'Goa', 'Chennai', 'Hyderabad', 'Kolkata', 'Pune', 'Udaipur'];
  let city = 'Mumbai';
  for (const c of cities) {
    if (new RegExp(`\\b${c}\\b`, 'i').test(req.brief)) {
      city = c;
      break;
    }
  }

  return {
    fields: {
      title: `${city} ${type.charAt(0).toUpperCase() + type.slice(1)} Celebration`,
      type,
      city,
      guests,
      budgetMinor,
      notes: req.brief.slice(0, 500),
    },
    source: 'fallback',
  };
}

/** Grounded plan assistant answer from plan summary */
export function generateFallbackAssistant(req: AssistantRequest): AssistantResult {
  const { question, planSummary } = req;
  const q = question.toLowerCase();

  let answer = `Regarding your ${planSummary.eventType} with ${String(planSummary.momentCount)} moments: `;

  if (q.includes('budget') || q.includes('cost') || q.includes('money')) {
    answer += `Your planned budget is ₹${(planSummary.totalBudgetMinor / 100).toLocaleString('en-IN')}. With ${String(planSummary.guests)} guests, your allocation averages ₹${Math.round(planSummary.totalBudgetMinor / 100 / Math.max(1, planSummary.guests)).toLocaleString('en-IN')} per guest. Consider using the Trade-Off Simulator in the Plan Workspace if you need to free funds.`;
  } else if (q.includes('moment') || q.includes('schedule') || q.includes('cut')) {
    answer += `Your current signature moments are: ${planSummary.momentNames.join(', ')}. If you wish to streamline the day, visit the Moment Deck to resequence or simulate cutting a lower-importance moment.`;
  } else if (q.includes('vendor') || q.includes('caterer') || q.includes('venue')) {
    answer += `You can review and print dedicated vendor Cue Sheets in the Plan Workspace. Each vendor receives only the moments they serve along with key interview questions to ask.`;
  } else {
    answer += `To optimize your celebration, prioritize the moments rated 5/5 (signature moments), check the Energy Curve for pacing lulls, and share print-ready Cue Sheets with your vendors.`;
  }

  return {
    answer,
    source: 'fallback',
  };
}
